func (s *SegmentEmbed) MarshalYAML() (interface{}, error) {
 if _, _, err := s.parts(); err != nil { return nil, err }
 switch v := s.Segment.(type) {
 case SegmentKey: return string(v), nil
 case Segments:
  if len(v.Keys) == 1 { v.SegmentOperator = "OR_SEGMENT_OPERATOR" }
  return v, nil
 default: return nil, fmt.Errorf("invalid segment format")
 }
}

