  if _, ok := v["operator"]; !ok { return fmt.Errorf("segment object requires operator") }
  var segments Segments
  if err := unmarshal(&segments); err != nil { return err }
  s.Segment = segments
 default:
  return fmt.Errorf("invalid segment format %T", raw)
 }
 _, _, err := s.parts()
 return err
}

